const http = $json || {};
const envelope = http.body && typeof http.body === 'object' ? http.body : http;
const technical = (reason) => [{ json: { status: 'ABSTAIN_TECHNICAL', not_a_verdict: true, live_mvr_scoring_executed: false, human_review_required: true, action_authorized: false, reason, next_step: 'Review the connector response before retrying. No market action is authorized.' } }];
if (http.statusCode !== undefined && http.statusCode !== 200) return technical('mcp_http_error');
if (envelope.error || envelope.result?.isError) return technical('mcp_json_rpc_error');
const result = envelope.result?.structuredContent;
if (!result || typeof result !== 'object') return technical('missing_structured_content');
if (result.not_a_verdict !== true || result.live_mvr_scoring_executed !== false) return technical('public_boundary_mismatch');
const gaps = Array.isArray(result.evidence_gaps) ? result.evidence_gaps.slice(0, 10) : [];
const unlocks = Array.isArray(result.next_three_unlocks) ? result.next_three_unlocks.slice(0, 3) : [];
return [{ json: { status: 'DISCOVERY_ONLY', not_a_verdict: true, live_mvr_scoring_executed: false, decision_domain: result.decision_domain || null, max_safe_action_available_now: result.max_safe_action_available_now || 'Continue with bounded discovery only.', evidence_gaps: gaps, next_three_unlocks: unlocks, human_review_required: true, action_authorized: false, attribution: result.attribution || 'Minimum Viable Relationships (MVR), originated by Farouk Mark Mukiibi, African Market OS.' } }];
